// Native PCM noise descriptors; no sequence or internal-clock oracle.
package main
import("crypto/sha256";"encoding/json";"flag";"fmt";"math";"os";"sort")
type lattice struct{Divisor int `json:"candidate_divisor"`;Phase int `json:"phase_residue"`;TrainingChanges int `json:"training_sign_changes"`;HeldoutChanges int `json:"heldout_sign_changes"`;HeldoutContradictions int `json:"heldout_contradictions"`}
type noise_result struct{State string `json:"state"`;Samples int `json:"samples"`;First int `json:"first_input_sample"`;Last int `json:"last_input_sample"`;Low float64 `json:"low_level_pcm"`;High float64 `json:"high_level_pcm"`;Mid float64 `json:"level_midpoint_pcm"`;Span float64 `json:"level_span_pcm"`;RMS float64 `json:"rms_pcm"`;Mean float64 `json:"mean_pcm"`;Positive float64 `json:"high_population_fraction"`;Zeros float64 `json:"exact_zero_fraction"`;MaxResidual float64 `json:"maximum_two_level_residual_pcm"`;Outliers int `json:"two_level_outlier_samples"`;Tolerance float64 `json:"two_level_tolerance_pcm"`;Changes int `json:"sign_changes"`;TransitionFraction float64 `json:"sign_change_fraction"`;Runs map[int]int `json:"run_length_counts"`;Correlations map[int]float64 `json:"sign_correlations"`;Fits []lattice `json:"training_compatible_lattices"`;Compatible []int `json:"heldout_compatible_divisors"`;Coarsest int `json:"coarsest_compatible_divisor"`;RateState string `json:"rate_resolution"`;Assumptions []string `json:"assumptions"`}
type score_job struct{column string;start,end int}
func original_noise_cli_main(){var job score_job;flag.StringVar(&job.column,"column","right","PCM column");flag.IntVar(&job.start,"start-sample",0,"inclusive native sample bound");flag.IntVar(&job.end,"end-sample",0,"exclusive native bound;0=end");flag.Parse();e:=job.run();if e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(1)}}
func(job *score_job)run()error{if flag.NArg()!=1{return fmt.Errorf("use [-column NAME] [-start-sample N] [-end-sample N] INPUT.csv")};raw,e:=os.ReadFile(flag.Arg(0));if e!=nil{return e};v,e:=read_phase_csv(raw,job.column);if e!=nil{return e};if job.end==0{job.end=len(v)};if job.start<0||job.end>len(v)||job.end-job.start<256{return fmt.Errorf("invalid interval or fewer than256 samples")};for _,x:=range v{if x!=math.Trunc(x){return fmt.Errorf("PCM must be integral")}};result:=score_noise(v[job.start:job.end]);result.First=job.start;result.Last=job.end-1;output:=map[string]interface{}{"input":flag.Arg(0),"input_sha256":fmt.Sprintf("%x",sha256.Sum256(raw)),"column":job.column,"native_stride":1,"result":result};e=json.NewEncoder(os.Stdout).Encode(output);return e}
func score_noise(v []float64)noise_result{
 r:=noise_result{Samples:len(v),Runs:map[int]int{},Correlations:map[int]float64{},Compatible:[]int{},Fits:[]lattice{},Assumptions:[]string{"Native stride1 input required; no extra decimation","Two-level tolerance=max2PCM or0.1% span; qualified finite synthetic scope only","Sign changes reveal only sampled changes, never every hidden clock update","No IID acceptance, seed, exact sequence, polynomial, or full-period claim"}}
 lo,hi:=v[0],v[0];zero:=0;sum,square:=0.,0.;for _,x:=range v{if x<lo{lo=x};if x>hi{hi=x};if x==0{zero++};sum+=x;square+=x*x};r.Mean=sum/float64(len(v));r.RMS=math.Sqrt(square/float64(len(v)));r.Zeros=float64(zero)/float64(len(v));if zero==len(v){r.State="quiet_exact_zero";return r};if lo==hi{r.State="stuck_nonzero";r.Low=lo;r.High=hi;return r}
 midpoint:=(lo+hi)/2;lower,upper:=[]float64{},[]float64{};for _,x:=range v{if x<=midpoint{lower=append(lower,x)}else{upper=append(upper,x)}};sort.Float64s(lower);sort.Float64s(upper);r.Low=lower[len(lower)/2];r.High=upper[len(upper)/2];r.Mid=(r.Low+r.High)/2;r.Span=r.High-r.Low;r.Positive=float64(len(upper))/float64(len(v));r.Tolerance=math.Max(2,.001*r.Span)
 signs:=make([]bool,len(v));changes:=[]int{};run:=1;for i,x:=range v{signs[i]=x>r.Mid;target:=r.Low;if signs[i]{target=r.High};res:=math.Abs(x-target);if res>r.MaxResidual{r.MaxResidual=res};if res>r.Tolerance{r.Outliers++};if i>0{if signs[i]!=signs[i-1]{changes=append(changes,i);r.Runs[run]++;run=1}else{run++}}};r.Runs[run]++;r.Changes=len(changes);r.TransitionFraction=float64(r.Changes)/float64(len(v)-1)
 if r.Span<32{r.State="low_level_unresolved";return r};if r.Outliers>0{r.State="not_stationary_two_level";return r};if len(lower)<32||len(upper)<32||r.Changes<32{r.State="finite_transition_coverage_insufficient";return r};r.State="steady_two_level"
 for _,lag:=range []int{1,2,3,4,8,16,32,64}{sum:=0.;for i:=lag;i<len(signs);i++{if signs[i]==signs[i-lag]{sum++}else{sum--}};r.Correlations[lag]=sum/float64(len(signs)-lag)}
 split:=len(v)/2;for d:=1;d<=32;d++{accepted:=false;for phase:=0;phase<d;phase++{train,bad,held:=0,0,0;valid:=true;for _,n:=range changes{eligible:=(2*n+phase)/d!=(2*(n-1)+phase)/d;if n<split{train++;if !eligible{valid=false;break}}else{held++;if !eligible{bad++}}};if valid{r.Fits=append(r.Fits,lattice{d,phase,train,held,bad});if bad==0{accepted=true}}};if accepted{r.Compatible=append(r.Compatible,d);r.Coarsest=d}}
 if r.Coarsest<=2{r.RateState="unresolved_one_or_more_updates_per_native_sample"}else{r.RateState="compatible_sampled_update_lattice_not_unique_internal_clock"};return r
}
